# measurement pass first, then the asserts; print the verse, then slice; type the census the print made — a token census, a lemma census and a
# family count are three instruments). Nothing asserted here. Sitting 14's form (bor_measure1.py).
import json, os, re, html, sqlite3, sys, io, contextlib, unicodedata
from collections import Counter
ROOT = _ROOT
def clean(s): return re.sub(r'<[^>]+>', '', html.unescape(s))
def plain(w): return ''.join(c for c in w if c != '/' and not (0x0591 <= ord(c) <= 0x05C7))
def pointed(w): return ''.join(c for c in w if c != '/' and not (0x0591 <= ord(c) <= 0x05AF))
def NF(s): return unicodedata.normalize('NFC', s)
db = sqlite3.connect(f'file:{ROOT}/Data/tanakh.sqlite?mode=ro', uri=True)
rows = db.execute("SELECT v.book, v.chapter, v.verse, w.he, w.morph, w.lemma FROM words w JOIN verses v ON w.verse_id=v.id ORDER BY v.id, w.idx").fetchall()
by = {}
for b, c, v, he, m, lem in rows: by.setdefault((b, c, v), []).append((plain(he), m, he, lem))
T = ('Gen', 'Exod', 'Lev', 'Num', 'Deut')
C = 35; NV = 34
def words(b, c, v): return [x for x, _, _, _ in by[(b, c, v)]]
def morphs(b, c, v): return [m for _, m, _, _ in by[(b, c, v)]]
def wm(b, c, v): return [(x, m) for x, m, _, _ in by[(b, c, v)]]
def raw(b, c, v): return [(x, m, NF(pointed(r))) for x, m, r, _ in by[(b, c, v)]]
def hits(sub, books=None, exact=True): return sorted({f'{b} {c}:{v}' for (b, c, v), ws in by.items() if (books is None or b in books) and any((x == sub) if exact else (sub in x) for x, _, _, _ in ws)})
def phrase(seq, books=None):
    out = []
    for (b, c, v), ws in by.items():
        if books is not None and b not in books: continue
        w = [x for x, _, _, _ in ws]
        if any(w[i:i + len(seq)] == list(seq) for i in range(len(w) - len(seq) + 1)): out.append(f'{b} {c}:{v}')
    return sorted(out)
def U(*toks, books=None): return sorted(set(s for t in toks for s in hits(t, books)))
def LEM(lem, books=None): return sorted({f'{b} {c}:{v}' for (b, c, v), ws in by.items() if (books is None or b in books) for x, _, _, l in ws if l == lem})
def lemma_of(b, c, v, tok): return [l for x, _, _, l in by[(b, c, v)] if x == tok]
def cnt(pred, books=None): return sum(1 for (b, c, v), ws in by.items() if books is None or b in books for x, m, _, _ in ws if pred(x, m))
def in35(pred): return [(v, x) for v in range(1, NV + 1) for x, m, _, _ in by[('Num', C, v)] if pred(x, m)]
onk = json.load(open(f'{ROOT}/Data/sefaria_export/Onkelos_Numbers/en.json'))['text']
onk_he = json.load(open(f'{ROOT}/Data/sefaria_export/Onkelos_Numbers/he.json'))['text']
def arm(c, v): return [plain(x) for x in clean(onk_he[c - 1][v - 1]).rstrip(':').split()]
def onk_seats(sub): return [(c + 1, v + 1) for c in range(36) for v in range(len(onk_he[c])) if sub in ' '.join(arm(c + 1, v + 1))]
def onk_tok(tok): return [(c + 1, v + 1) for c in range(36) for v in range(len(onk_he[c])) if tok in arm(c + 1, v + 1)]
sif = json.load(open(f'{ROOT}/Data/sefaria_export/Sifrei_Bamidbar/en.json'))['text']; sif_he = json.load(open(f'{ROOT}/Data/sefaria_export/Sifrei_Bamidbar/he.json'))['text']
